<?php
$id = req_int('id'); $e = row("SELECT * FROM employees WHERE id=?", [$id]); if (!$e) throw new UserError('کارمند یافت نشد');
$ym = str_replace('/', '-', en_num((string)($_GET['ym'] ?? jym(today()))));
$f = ['name' => ['نام', 'text', 1], 'national_id' => ['کدِ ملی', 'text'], 'mobile' => ['موبایل', 'text'], 'unit' => ['واحد', 'text'], 'position' => ['سمت', 'text'], 'contract_type' => ['نوعِ قرارداد', 'select', 1, ['full' => 'تمام‌وقت', 'part' => 'پاره‌وقت', 'hourly' => 'ساعتی', 'project' => 'پروژه‌ای']],
    'base_salary' => ['حقوقِ پایه', 'money'], 'hire_date' => ['استخدام', 'date'], 'married' => ['متأهل', 'check'], 'children' => ['فرزند', 'int'], 'uninsured' => ['بدونِ بیمه', 'check'], 'iban' => ['شبا', 'text'], 'user_id' => ['کاربرِ سامانه', 'select', 0, ui_opts("SELECT id, name FROM users WHERE kind='staff'")], 'inactive' => ['غیرفعال', 'check']];
echo ui_card($e['name'], can('hr.edit') ? ui_form('employee_save', $f, $e + ['uninsured' => !$e['insured'], 'inactive' => !$e['active']], ['hidden' => ['id' => $id]]) : '');
echo '<div class="cols">';
$cs = rows("SELECT * FROM contracts WHERE employee_id=? ORDER BY id DESC", [$id]);
echo ui_card('قراردادها', ui_table(['title' => 'عنوان', 'start_date' => ['از', 'date'], 'salary' => ['حقوق', 'money'], 'signed_at' => ['امضا', fn($r) => $r['signed_at'] ? ui_badge('امضاشده ' . jdate($r['signed_at']), 'ok') . '<br><code>' . h(substr($r['hash'], 0, 16)) . '…</code>' : (can('hr.edit') ? ui_btn_api('امضا با کدِ پیامکیِ کارمند', 'contract_sign', ['id' => $r['id'], 'method' => 'otp'], ['class' => 'sm', 'prompt' => 'otp:کدی که به موبایلِ کارمند رفت']) . ' ' . ui_btn_api('امضای حضوری', 'contract_sign', ['id' => $r['id'], 'method' => 'manual'], ['class' => 'sm', 'confirm' => 'نسخهٔ کاغذی امضا شد؟']) : '')]], $cs)
    . (can('hr.edit') ? ui_form('contract_save', ['title' => ['عنوان', 'text', 1, [], 'قراردادِ کار'], 'start' => ['از', 'date', 1], 'end' => ['تا', 'date'], 'salary' => ['حقوق', 'money'], 'body' => ['متن', 'textarea', 1]], [], ['hidden' => ['employee_id' => $id], 'submit' => 'افزودنِ قرارداد']) : ''));
$att = attendance_month($id, $ym);
echo ui_card('کارکردِ ' . fa_num($ym), '<p>روزِ حضور ' . fa_num($att['days']) . ' · تأخیر ' . fa_num($att['late']) . ' دقیقه · اضافه‌کار ' . fa_num($att['over']) . ' دقیقه · مرخصی ' . fa_num((string)$att['leave_paid']) . ' روز (بی‌حقوق ' . fa_num((string)$att['leave_unpaid']) . ')</p>'
    . ui_table(['d' => ['روز', 'date'], 't_in' => ['ورود', 'num'], 't_out' => ['خروج', 'num'], 'late_min' => ['تأخیر', 'num'], 'over_min' => ['اضافه‌کار', 'num']], $att['rows']));
echo ui_card('مرخصی — مانده: ' . fa_num((string)leave_balance($id)) . ' روز', (can('hr.attendance') ? ui_form('leave_request', ['kind' => ['نوع', 'select', 1, leave_kinds()], 'from' => ['از', 'date', 1], 'to' => ['تا', 'date'], 'days' => ['تعدادِ روز (خالی = محاسبه)', 'float'], 'note' => ['توضیح', 'text']], [], ['hidden' => ['employee_id' => $id]]) : '')
    . ui_table(['kind' => ['نوع', fn($r) => h(leave_kinds()[$r['kind']] ?? '')], 'from_d' => ['از', 'date'], 'to_d' => ['تا', 'date'], 'days' => ['روز', 'num']], rows("SELECT * FROM leaves WHERE employee_id=? ORDER BY id DESC LIMIT 30", [$id])));
echo ui_card('فیش‌های حقوق', ui_table(['ym' => ['ماه', 'num'], 'gross' => ['ناخالص', 'money'], 'deductions' => ['کسورات', 'money'], 'net' => ['خالص', 'money'], 'status' => 'وضعیت', 'p' => ['', fn($r) => '<a class="btn sm" target="_blank" href="index.php?p=print_payslip&id=' . $r['id'] . '">فیش</a>']], rows("SELECT * FROM payslips WHERE employee_id=? ORDER BY ym DESC", [$id])));
echo '</div>';
